<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {api,base,image} from './book-api'
import {createId} from './id'
import UnitThumb from './UnitThumb.vue'
import PhotoThumb from './PhotoThumb.vue'
import TemplatePreview from './TemplatePreview.vue'
import {layerCategories,visibleLayerIds} from './layer-categories'
import {replaceInMask} from './photo-slot'
import {saveDraft,listDrafts,deleteDraft} from './storage'
const books=ref<any[]>([]),catalog=ref<any[]>([]),active=ref<any>(null),picker=ref(false),selection=ref<any>(null),filter=ref('journal'),query=ref(''),error=ref(''),busy=ref(false),saving=ref(''),index=ref(0),previews=ref<Record<string,string>>({}),turn=ref(''),directory=ref(false),file=ref<HTMLInputElement>(),replace=ref<any>(null),replacement=ref(''),exportUrl=ref('')
const hiddenCategories=ref<string[]>([]),filterBusy=ref(false),previewLoading=ref(false)
let filterEpoch=0
function resetLayerPreview(){filterEpoch++;hiddenCategories.value=[];filteredPages.value={};filterBusy.value=false}
const filteredPages=ref<Record<string,string>>({})
const phase=ref(''),preloadStatus=ref('')
const flipFront=ref(''),flipBack=ref(''),templateScroll=ref<HTMLElement>(),themeFilter=ref('全部')
const themeOptions=['全部','生日纪念','爱情故事','亲子时光','山野自然','城市漫游']
function scrollTemplates(direction:number){templateScroll.value?.scrollBy({left:direction*(templateScroll.value.clientWidth*.82),behavior:'smooth'})}
let token=0,touch=0,history:any[]=[],projectionCache=new Map<string,any>()
const units=computed(()=>active.value?.units||[]),unit=computed(()=>units.value[index.value]),visible=computed(()=>unit.value?[unit.value.leftPageID,unit.value.rightPageID]:[]),filtered=computed(()=>catalog.value.filter(b=>b.kind===filter.value&&b.title.includes(query.value)&&(themeFilter.value==='全部'||b.theme===themeFilter.value))),recent=computed(()=>[...books.value].sort((a,b)=>(b.lastViewedAt||0)-(a.lastViewedAt||0))[0])
const spreadRatio=computed(()=>{const p=active.value?.pages.find((p:any)=>visible.value.includes(p.id));return p?.size?.width>0&&p?.size?.height>0?2*p.size.width/p.size.height:1.38})
const photoGroups=computed(()=>visible.value.map((id:any,i:number)=>({id,side:i?'右页照片':'左页照片',slots:active.value?.pages.find((p:any)=>p.id===id)?.slots.filter((s:any)=>s.kind==='photo')||[]})).filter((g:any)=>g.id&&g.slots.length))
async function refresh(){books.value=(await listDrafts()).filter((d:any)=>d.type==='book').sort((a:any,b:any)=>b.updatedAt-a.updatedAt)}
async function persist(){saving.value='保存中';const snapshot=JSON.parse(JSON.stringify(active.value));delete snapshot.hiddenCategories;try{await saveDraft(snapshot);const i=books.value.findIndex(b=>b.id===snapshot.id);if(i>=0)books.value[i]=snapshot;else books.value.push(snapshot);saving.value='已保存到此浏览器'}catch{saving.value='保存失败，请及时导出';error.value='浏览器存储不可用或空间不足'}}
async function showPicker(){picker.value=true;busy.value=true;try{catalog.value=(await api('books/')).items}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function add(){if(!selection.value||busy.value)return;busy.value=true;try{const b=selection.value;const data=await api(base(b)+'browse/');const book={...data,id:createId(),type:'book',sourceId:b.id,cover:b.cover,pageCount:b.pageCount,overrides:{},replacements:{},lastIndex:0,updatedAt:Date.now()};await saveDraft(book);picker.value=false;await refresh();await open(book)}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function open(b:any){active.value=JSON.parse(JSON.stringify(b));delete active.value.hiddenCategories;resetLayerPreview();index.value=b.lastIndex||0;previews.value={};history=[];projectionCache.clear();filteredPages.value={};active.value.lastViewedAt=Date.now();await persist();await loadVisible()}
async function preview(id:string,small=false){if(!id)return '';const bookId=active.value?.id;const key=id+(small?':small':'');if(previews.value[key])return previews.value[key];const result=await api(base(active.value)+`pages/${id}/preview/${small?'?small=1':''}`);if(active.value?.id===bookId)previews.value[key]=result.url;return result.url}
async function loadVisible(){const request=++token;previewLoading.value=true;preloadStatus.value='';try{await Promise.all(visible.value.filter(Boolean).map((id:string)=>preview(id)));if(request===token){void warmCurrentPages(request);const next=units.value[index.value+1];if(next)for(const id of [next.leftPageID,next.rightPageID].filter(Boolean))preview(id).catch(()=>{})}}catch(e:any){if(request===token)error.value=e.message}finally{if(request===token)previewLoading.value=false}}
function navigate(n:number){if(n<0||n>=units.value.length||n===index.value||turn.value||busy.value)return;const u=units.value[n],forward=n>index.value;flipFront.value=source(visible.value[forward?1:0]);flipBack.value=active.value.overrides?.[forward?u.leftPageID:u.rightPageID]||previews.value[forward?u.leftPageID:u.rightPageID]||'';resetLayerPreview();error.value='';index.value=n;active.value.lastIndex=n;turn.value=forward?'next':'prev';void loadVisible();void persist();setTimeout(()=>{turn.value=''},520)}
function source(id:string){if(hiddenCategories.value.length)return filteredPages.value[id]||'';return active.value?.overrides?.[id]||previews.value[id]||''}
async function remove(b:any){if(confirm('删除这本本机手帐？')){await deleteDraft(b.id);await refresh()}}
function begin(g:any,s:any){if(busy.value||turn.value)return;replace.value={pageId:g.id,slot:s};replacement.value='';file.value?.click()}
async function chosen(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f){replace.value=null;return}busy.value=true;phase.value='正在读取所选照片…';try{if(f.size>20*1024*1024)throw Error('照片不能超过20 MB');const url=URL.createObjectURL(f);try{const im=await image(url);if(im.width*im.height>50000000)throw Error('照片像素过大');const c=document.createElement('canvas'),s=Math.min(1,3000/Math.max(im.width,im.height));c.width=im.width*s;c.height=im.height*s;c.getContext('2d')!.drawImage(im,0,0,c.width,c.height);replacement.value=c.toDataURL('image/jpeg',.92)}finally{URL.revokeObjectURL(url)}await confirmReplace()}catch(e:any){error.value=e.message;replace.value=null}finally{busy.value=false;phase.value='';(e.target as HTMLInputElement).value=''}}
async function project(id:string){if(projectionCache.has(id))return projectionCache.get(id);const promise=api(base(active.value)+`pages/${id}/projection/`);projectionCache.set(id,promise);try{const result=await promise;setTimeout(()=>{if(projectionCache.get(id)===promise)projectionCache.delete(id)},12*60*1000);return result}catch(e){if(projectionCache.get(id)===promise)projectionCache.delete(id);throw e}}
async function warmCurrentPages(request:number){const ids=visible.value.filter((id:string)=>id&&active.value.pages.find((p:any)=>p.id===id)?.slots.some((s:any)=>s.kind==='photo'));preloadStatus.value=ids.length?'正在后台加载当前页照片素材…':'';try{for(const id of ids){if(request!==token)return;const d=await project(id);if(request!==token)return;await Promise.all(Object.values(d.assets).map((a:any)=>image(a.url)))}if(request===token)preloadStatus.value='当前跨页素材已就绪'}catch{if(request===token)preloadStatus.value='部分素材未就绪，替换时将重试'}}
async function compose(id:string,hidden:string[]=[]){const replacements=active.value.replacements[id]||{};const d=await project(id),imgs:Record<string,HTMLImageElement>={};let loaded=0;const assets=Object.entries(d.assets) as any;phase.value=`加载当前页素材 0/${assets.length}`;await Promise.all(assets.map(async([aid,a]:any)=>{imgs[aid]=await image(a.url);phase.value=`加载当前页素材 ${++loaded}/${assets.length}`}));phase.value='正在合成照片…';await new Promise<void>(r=>requestAnimationFrame(()=>r()));const visibleIds=new Set(visibleLayerIds(d.objects,d.page.rootContentID,hidden));const c=document.createElement('canvas');const scale=Math.min(1,2048/d.page.size.height);c.width=d.page.size.width*scale;c.height=d.page.size.height*scale;const ctx=c.getContext('2d')!;ctx.scale(scale,scale)
async function draw(oid:string,depth=0){if(depth>32)throw Error('模板层级过深');const obj=d.objects[oid];if(!obj)throw Error('模板缺少图层');for(const l of obj.layers){if(l.visible===false)continue;if(!l.contentID&&!visibleIds.has(l.id))continue;ctx.save();const t=l.transform||{},p=t.position||{},v=t.pivot||{};ctx.translate(p.x||0,p.y||0);ctx.rotate((t.rotationDegrees||0)*Math.PI/180);ctx.scale(t.scale??1,t.scale??1);ctx.translate(-(v.x||0),-(v.y||0));if(l.contentID)await draw(l.contentID,depth+1);else if(l.assetID&&imgs[l.assetID]){const original=imgs[l.assetID],r=replacements[l.id];if(r){const im=await image(r.src),tmp=replaceInMask(original,im,r.zoom,r.fill);ctx.drawImage(tmp,0,0,l.size.width,l.size.height);tmp.width=tmp.height=0}else ctx.drawImage(original,0,0,l.size.width,l.size.height)}ctx.restore()}}
await draw(d.page.rootContentID);return c.toDataURL(hidden.length?'image/png':'image/jpeg',.94)}
async function confirmReplace(){if(!replacement.value)return;busy.value=true;const before=JSON.parse(JSON.stringify(active.value));try{const {pageId,slot}=replace.value;phase.value='正在准备当前页图层…';const d=await project(pageId);let found=false;for(const o of Object.values(d.objects) as any)for(const l of o.layers||[])if(l.id===slot.layerID&&l.assetID)found=true;if(!found)throw Error('该照片槽尚未完成 Web 映射，无法替换');active.value.replacements[pageId]??={};active.value.replacements[pageId][slot.layerID]={src:replacement.value,zoom:1,fill:'cover'};active.value.overrides[pageId]=await compose(pageId);delete filteredPages.value[pageId];await ensureFiltered([pageId]);history.push(before);if(history.length>20)history.shift();active.value.updatedAt=Date.now();phase.value='正在保存照片修改…';await new Promise<void>(r=>requestAnimationFrame(()=>r()));await persist();replace.value=null;replacement.value=''}catch(e:any){active.value=before;filteredPages.value={};error.value=e.message}finally{busy.value=false}}
async function undo(){if(history.length){active.value=history.pop();resetLayerPreview();await loadVisible();await persist()}}
async function ensureFiltered(ids:string[]){const hidden=[...hiddenCategories.value],epoch=filterEpoch;if(!hidden.length)return;for(const id of ids){if(!filteredPages.value[id]){const result=await compose(id,hidden);if(epoch!==filterEpoch)return;filteredPages.value[id]=result}}}
async function toggleCategory(id:string){if(busy.value||turn.value||filterBusy.value)return;const before=[...hiddenCategories.value],previous={...filteredPages.value},epoch=++filterEpoch;filterBusy.value=true;error.value='';hiddenCategories.value=before.includes(id)?before.filter(x=>x!==id):[...before,id];filteredPages.value={};try{await ensureFiltered(visible.value.filter(Boolean))}catch(e:any){if(epoch===filterEpoch){hiddenCategories.value=before;filteredPages.value=previous;error.value=e.message}}finally{if(epoch===filterEpoch)filterBusy.value=false}}
async function exportSpread(){busy.value=true;try{const c=document.createElement('canvas');c.width=2400;c.height=1720;const x=c.getContext('2d')!;x.fillStyle='#453b2a';x.fillRect(0,0,c.width,c.height);for(let i=0;i<2;i++){const id=visible.value[i];if(!id)continue;const im=await image(source(id)||await preview(id));const s=Math.min(1180/im.width,1680/im.height);x.drawImage(im,i*1200+(1200-im.width*s)/2,(1720-im.height*s)/2,im.width*s,im.height*s)}const blob=await new Promise<Blob|null>(r=>c.toBlob(r,'image/jpeg',.94));if(!blob)throw Error('无法生成图片');if(exportUrl.value)URL.revokeObjectURL(exportUrl.value);exportUrl.value=URL.createObjectURL(blob)}catch(e:any){error.value=e.message+'；请确认素材跨域配置允许导出'}finally{busy.value=false}}
function closeExport(){URL.revokeObjectURL(exportUrl.value);exportUrl.value=''}
onMounted(()=>{refresh().then(async()=>{if(!books.value.length)return;try{const current=(await api('books/')).items;for(const b of books.value){const match=current.find((x:any)=>x.id===b.sourceId);if(match)b.cover=match.cover}}catch{/* Keep local shelf usable when offline. */}}).catch(()=>error.value='无法读取此浏览器的本机手帐');window.addEventListener('keydown',e=>{if((e.target as HTMLElement)?.matches('input,textarea')||picker.value||replace.value||!active.value)return;if(e.key==='ArrowRight')navigate(index.value+1);if(e.key==='ArrowLeft')navigate(index.value-1)})})
</script>
<template>
<div class="app-shell" :class="{'is-reading':!!active}">
<header class="book-header"><template v-if="!active"><span class="brand-mark">◒</span><h1>我的手帐</h1><button class="circle" aria-label="添加模板" @click="showPicker">＋</button></template><template v-else><button class="circle" aria-label="返回首页" @click="token++;resetLayerPreview();active=null" :disabled="busy">‹</button><h1>{{active.title}}</h1><div class="header-tools"><button :disabled="busy||filterBusy||previewLoading" @click="exportSpread" aria-label="保存当前跨页">↥</button><button @click="directory=!directory" aria-label="目录">☷</button></div></template></header>
<div v-if="error" class="error" role="alert">{{error}}<button @click="error=''">关闭</button></div>
<main v-if="!active" class="shelf"><template v-if="books.length"><h2>继续创作</h2><article class="continue-card"><img :src="recent.cover" alt="封面"><div><h3>{{recent.title}}</h3><p>上次浏览第 {{(recent.lastIndex||0)+1}} 个跨页</p><button class="accent" @click="open(recent)">✎ 继续浏览</button></div></article><div class="row"><h2>全部手帐 · {{books.length}} 本</h2><span>↕ 最近修改</span></div><div class="books-grid"><article v-for="b in books" :key="b.id"><button class="book-card" @click="open(b)"><img :src="b.cover" :alt="b.title"><h3>{{b.title}}</h3><small>{{b.pageCount}} 页 · 已添加</small></button><button class="remove" @click="remove(b)">删除</button></article></div></template><div v-else class="empty"><div class="empty-book">✳</div><h2>把旅行装进一本手帐</h2><p>选一本喜欢的模板，翻开旅途，换上自己的照片。</p><button class="accent" @click="showPicker">＋ 添加模板</button></div><p class="privacy">免登录 · 照片本地处理 · 作品仅保存在当前浏览器</p></main>
<main v-else class="reader"><div class="reader-status" role="status" aria-live="polite">{{busy?(phase||'正在处理…'):filterBusy?'正在更新当前跨页展示…':previewLoading?'正在加载页面预览…':(preloadStatus||saving)}}</div><div class="physical-book" :class="turn" :style="{'--spread-ratio':spreadRatio}" @touchstart="touch=$event.touches[0].clientX" @touchend="Math.abs($event.changedTouches[0].clientX-touch)>60&&navigate(index+($event.changedTouches[0].clientX<touch?1:-1))"><div class="paper left"><img v-if="visible[0]&&source(visible[0])" :src="source(visible[0])" alt="左页"><span v-else class="leather"><span v-if="visible[0]" class="page-loading">加载中…</span></span></div><div class="paper right"><img v-if="visible[1]&&source(visible[1])" :src="source(visible[1])" alt="右页"><span v-else class="leather"><span v-if="visible[1]" class="page-loading">加载中…</span></span></div><div v-if="turn" class="turning-leaf"><div class="leaf-front"><img v-if="flipFront" :src="flipFront" alt="翻动纸张正面"></div><div class="leaf-back"><img v-if="flipBack" :src="flipBack" alt="翻动纸张背面"></div></div></div><div class="photo-groups"><div v-for="g in photoGroups" :key="g.id"><small>{{g.side}}</small><div class="photo-slots"><button v-for="(s,i) in g.slots" :key="s.slotID" @click="begin(g,s)" :disabled="busy||!!turn" :aria-label="`替换${s.label}`"><PhotoThumb :key="active.id+g.id+s.layerID" :base="base(active)" :page-id="g.id" :layer-id="s.layerID" :label="s.label" :replacement="active.replacements[g.id]?.[s.layerID]?.src"/><small>{{s.label.replace('照片_','')}}</small></button></div></div></div><div class="layer-controls" role="group" aria-label="分层显示"><button v-for="category in layerCategories" :key="category.id" :class="{enabled:!hiddenCategories.includes(category.id)}" :aria-pressed="!hiddenCategories.includes(category.id)" :aria-label="`${category.title}：${hiddenCategories.includes(category.id)?'隐藏':'显示'}`" :disabled="busy||!!turn||filterBusy" @click="toggleCategory(category.id)"><span class="layer-symbol" aria-hidden="true">{{category.icon}}</span><span>{{category.title}}</span><span v-if="hiddenCategories.includes(category.id)" class="hidden-indicator" aria-hidden="true">−</span></button></div><div class="page-navigation"><button :disabled="index===0||busy||!!turn" @click="navigate(index-1)">‹</button><span>{{index+1}} / {{units.length}} · 跨页</span><button :disabled="index===units.length-1||busy||!!turn" @click="navigate(index+1)">›</button></div><div class="unit-strip"><button v-for="(u,i) in units" :class="{selected:index===i}" @click="navigate(Number(i))"><UnitThumb :unit="u" :base="base(active)"/><small>{{Number(i)+1}} · {{u.title}}</small></button></div><button v-if="history.length" @click="undo">↶ 撤销上一次替换</button><p class="privacy">只加载浏览及替换所需页面 · 替换照片不会上传</p></main>
<div v-if="picker" class="scrim" @click.self="picker=false"><section class="template-sheet" role="dialog" aria-modal="true" aria-label="添加模板"><div class="handle"></div><div class="sheet-top"><input v-model="query" placeholder="搜索手帐名称"><div class="segments"><button :class="{selected:filter==='journal'}" @click="filter='journal'">手帐</button><button :class="{selected:filter==='album'}" @click="filter='album'">相册</button></div><button @click="picker=false">×</button></div><p v-if="busy">正在读取模板目录…</p><p v-if="!busy&&!filtered.length">暂无匹配模板，请清除搜索或切换分类。</p><div class="theme-row"><div class="theme-tabs"><button v-for="t in themeOptions" :key="t" :class="{selected:themeFilter===t}" @click="themeFilter=t">{{t}}</button></div><div class="carousel-arrows"><button aria-label="向左浏览模板" @click="scrollTemplates(-1)">‹</button><button aria-label="向右浏览模板" @click="scrollTemplates(1)">›</button></div></div><div ref="templateScroll" class="template-scroll"><button v-for="b in filtered" :key="b.id" class="template-option" :class="{selected:selection?.id===b.id}" @click="selection=b"><TemplatePreview :book="b"/><div class="template-title"><h3>{{b.title}}</h3><span class="theme-tag">{{b.theme}}</span></div><small>{{b.pageCount}} 页 <span v-if="books.some(x=>x.sourceId===b.id)"> · ✓ 已添加</span><span v-else> · 按需加载</span></small></button></div><div class="sheet-bottom"><p>浏览封面与两个跨页预览 · 添加时不下载整本素材</p><button class="accent" :disabled="!selection||busy" @click="add">{{busy?'正在添加…':'添加并打开'}}</button></div></section></div>
<input ref="file" type="file" hidden accept="image/jpeg,image/png,image/webp,image/heic" @change="chosen">
<div v-if="directory" class="scrim" @click.self="directory=false"><section class="replace-sheet"><h2>目录</h2><button v-for="(u,i) in units" class="directory-item" @click="directory=false;navigate(Number(i))">{{Number(i)+1}} · {{u.title}}</button><button @click="directory=false">关闭</button></section></div>
<div v-if="exportUrl" class="scrim"><section class="replace-sheet"><h2>当前跨页图片已生成</h2><img class="export-preview" :src="exportUrl" alt="跨页成品"><a class="accent" :href="exportUrl" download="TravelDiary.jpg">下载图片</a><p>下载不可用时，可长按图片保存。</p><button @click="closeExport">返回手帐</button></section></div>
</div>
</template>
